/**
 * Embedding the adapter trees in the binary (ARCHITECTURE §9 "one binary").
 *
 * `bun build --compile` bundles only what the module graph imports, and file imports of
 * extension-less files (the `bin/agent-peers` shim) or dot-dirs do not type-check cleanly. So the
 * build generates `src/assets/adapters.generated.ts`: every adapter file as base64 plus its mode. It
 * is committed like the adapters' own generated files; `--check` (and a test) report drift.
 */
import { readdir, readFile, stat } from 'node:fs/promises'
import { join, relative, sep } from 'node:path'

export interface EmbeddedFile {
  /** Path relative to `adapters/`, with `/` separators. */
  readonly path: string
  /** 0o755 for executables, 0o644 otherwise. */
  readonly mode: number
  readonly base64: string
}

/** Adapter trees copied whole. */
export const EMBEDDED_TREES = ['claude-code', 'codex', 'claude-desktop'] as const
/** Single files outside those trees. */
export const EMBEDDED_FILES_EXTRA = ['marketplace/.claude-plugin/marketplace.json'] as const
const SKIPPED_NAMES: ReadonlySet<string> = new Set(['.gitignore', '.DS_Store'])

export const GENERATED_MODULE = join('src', 'assets', 'adapters.generated.ts')

async function walk(dir: string): Promise<readonly string[]> {
  const entries = await readdir(dir, { withFileTypes: true })
  const nested = await Promise.all(
    entries
      .filter((entry) => !SKIPPED_NAMES.has(entry.name))
      .map(async (entry) => {
        const path = join(dir, entry.name)
        if (entry.isDirectory()) return walk(path)
        return entry.isFile() ? [path] : []
      }),
  )
  return nested.flat()
}

async function embed(adaptersDir: string, path: string): Promise<EmbeddedFile> {
  const [bytes, info] = await Promise.all([readFile(path), stat(path)])
  return {
    path: relative(adaptersDir, path).split(sep).join('/'),
    mode: (info.mode & 0o111) !== 0 ? 0o755 : 0o644,
    base64: bytes.toString('base64'),
  }
}

/** Every embedded file, sorted by path. */
export async function collectAdapterFiles(adaptersDir: string): Promise<readonly EmbeddedFile[]> {
  const trees = await Promise.all(EMBEDDED_TREES.map((tree) => walk(join(adaptersDir, tree))))
  const paths = [...trees.flat(), ...EMBEDDED_FILES_EXTRA.map((file) => join(adaptersDir, file))]
  const files = await Promise.all(paths.map((path) => embed(adaptersDir, path)))
  return [...files].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
}

/** Biome's line width (biome.json); a longer `base64: '…',` line is broken after the colon. */
const LINE_WIDTH = 110

function renderEntry(file: EmbeddedFile): string {
  const inline = `    base64: '${file.base64}',`
  const base64 = inline.length <= LINE_WIDTH ? `${inline}\n` : `    base64:\n      '${file.base64}',\n`
  return `  {\n    path: '${file.path}',\n    mode: 0o${file.mode.toString(8)},\n${base64}  },\n`
}

/** The generated module's text, formatted the way Biome leaves it. */
export function renderEmbeddedModule(files: readonly EmbeddedFile[]): string {
  const entries = files.map(renderEntry)
  return [
    '/**\n',
    ' * Generated by `bun packages/cli/scripts/embed-adapters.ts` from adapters/. Do not edit.\n',
    ' * Check for drift with `bun packages/cli/scripts/embed-adapters.ts --check`.\n',
    ' */\n',
    "import type { EmbeddedFile } from './embed'\n",
    '\n',
    'export const EMBEDDED_ADAPTERS: readonly EmbeddedFile[] = [\n',
    ...entries,
    ']\n',
  ].join('')
}

export interface EmbedResult {
  readonly code: number
  readonly message: string
}

/** Writes (or with `check`, verifies) `<cliDir>/src/assets/adapters.generated.ts`. */
export async function runEmbed(adaptersDir: string, cliDir: string, check: boolean): Promise<EmbedResult> {
  const text = renderEmbeddedModule(await collectAdapterFiles(adaptersDir))
  const target = join(cliDir, GENERATED_MODULE)
  const current = await readFile(target, 'utf8').catch(() => undefined)
  if (current === text) return { code: 0, message: `${GENERATED_MODULE}: up to date` }
  if (check) return { code: 1, message: `${GENERATED_MODULE}: stale (run bun scripts/embed-adapters.ts)` }
  await Bun.write(target, text)
  return { code: 0, message: `wrote ${GENERATED_MODULE}` }
}
